package com.gildedledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.gildedledger.tracking.GroundDropLedger;
import com.gildedledger.tracking.TileKey;
import java.util.Collections;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

public class GroundDropLedgerTest
{
	private static final int WHIP = 4151;
	private static final int BONES = 526;
	private static final TileKey NPC_TILE = new TileKey(3200, 3200, 0);
	private static final TileKey DROP_TILE = new TileKey(3200, 3200, 0);

	private GroundDropLedger ledger;

	@Before
	public void setUp()
	{
		ledger = new GroundDropLedger();
	}

	private void killDropping(int itemId, int quantity, TileKey where, int tick)
	{
		ledger.recordSpawn(where, itemId, quantity, tick);
		ledger.tagNpcLoot("npc:Abyssal demon", true, NPC_TILE, 1,
			Collections.singletonList(new int[]{itemId, quantity}), tick);
	}

	@Test
	public void takenByPlayerCountsAsLoot()
	{
		killDropping(WHIP, 1, DROP_TILE, 10);
		ledger.recordTake(DROP_TILE, WHIP, 12);

		List<GroundDropLedger.Pickup> pickups = ledger.recordRemoval(DROP_TILE, WHIP, 1, 14, DROP_TILE);

		assertEquals(1, pickups.size());
		assertEquals("npc:Abyssal demon", pickups.get(0).sourceKey);
		assertEquals(1, pickups.get(0).quantity);
		assertTrue(pickups.get(0).taskTarget);
	}

	@Test
	public void despawnWithoutTakeIsIgnored()
	{
		killDropping(WHIP, 1, DROP_TILE, 10);

		assertTrue(ledger.recordRemoval(DROP_TILE, WHIP, 1, 300, new TileKey(3210, 3210, 0)).isEmpty());
	}

	@Test
	public void takeFromFarAwayDoesNotCount()
	{
		killDropping(WHIP, 1, DROP_TILE, 10);
		ledger.recordTake(DROP_TILE, WHIP, 12);

		// Someone else grabbed it while we were still five tiles away.
		assertTrue(ledger.recordRemoval(DROP_TILE, WHIP, 1, 13, new TileKey(3205, 3200, 0)).isEmpty());
	}

	@Test
	public void itemsNotFromTheKillAreNeverLoot()
	{
		// The player drops their own item next to the corpse and picks it back up.
		ledger.recordSpawn(DROP_TILE, BONES, 1, 10);
		ledger.recordTake(DROP_TILE, BONES, 11);

		assertTrue(ledger.recordRemoval(DROP_TILE, BONES, 1, 12, DROP_TILE).isEmpty());
	}

	@Test
	public void partialStackPickupCountsOnlyWhatWasTaken()
	{
		killDropping(995, 5000, DROP_TILE, 10);
		ledger.recordTake(DROP_TILE, 995, 11);

		List<GroundDropLedger.Pickup> first = ledger.recordRemoval(DROP_TILE, 995, 3000, 12, DROP_TILE);
		assertEquals(3000, first.get(0).quantity);

		ledger.recordTake(DROP_TILE, 995, 13);
		List<GroundDropLedger.Pickup> second = ledger.recordRemoval(DROP_TILE, 995, 2000, 14, DROP_TILE);
		assertEquals(2000, second.get(0).quantity);

		ledger.recordTake(DROP_TILE, 995, 15);
		assertTrue(ledger.recordRemoval(DROP_TILE, 995, 1, 16, DROP_TILE).isEmpty());
	}

	@Test
	public void bossLootAwayFromTheBossStillMatches()
	{
		TileKey byPlayer = new TileKey(3208, 3204, 0);
		ledger.recordSpawn(byPlayer, WHIP, 1, 10);
		ledger.tagNpcLoot("npc:Zulrah", false, NPC_TILE, 5, Collections.singletonList(new int[]{WHIP, 1}), 10);
		ledger.recordTake(byPlayer, WHIP, 11);

		assertEquals(1, ledger.recordRemoval(byPlayer, WHIP, 1, 12, byPlayer).size());
	}

	@Test
	public void droppedLootPickedBackUpReturnsToItsSource()
	{
		ledger.recordPlayerDrop("gather:FISHING:Fly fishing", 335, 3, DROP_TILE, 10);
		ledger.recordTake(DROP_TILE, 335, 12);

		List<GroundDropLedger.Pickup> pickups = ledger.recordRemoval(DROP_TILE, 335, 3, 13, DROP_TILE);
		assertEquals(1, pickups.size());
		assertEquals("gather:FISHING:Fly fishing", pickups.get(0).sourceKey);
		assertEquals(3, pickups.get(0).quantity);
	}

	@Test
	public void oldSpawnsAreNotClaimedByALaterKill()
	{
		ledger.recordSpawn(DROP_TILE, WHIP, 1, 10);
		ledger.expire(20);
		ledger.tagNpcLoot("npc:Abyssal demon", false, NPC_TILE, 1, Collections.singletonList(new int[]{WHIP, 1}), 20);
		ledger.recordTake(DROP_TILE, WHIP, 21);

		assertTrue(ledger.recordRemoval(DROP_TILE, WHIP, 1, 22, DROP_TILE).isEmpty());
	}
}

package com.gildedledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.gildedledger.tracking.ItemRules;
import org.junit.Test;

public class ItemRulesTest
{
	@Test
	public void potionDoses()
	{
		assertEquals(4, ItemRules.doses("Prayer potion(4)"));
		assertEquals(2, ItemRules.doses("Divine super combat potion(2)"));
		assertEquals(1, ItemRules.doses("Shark"));
		assertEquals("Super restore", ItemRules.withoutDoses("Super restore(3)"));
		assertEquals(3000, ItemRules.perDoseValue(12000, "Prayer potion(4)"));
		assertEquals(0, ItemRules.perDoseValue(0, "Prayer potion(4)"));
	}

	@Test
	public void runesAreStackableItemsEndingInRune()
	{
		assertTrue(ItemRules.isRune("Blood rune", true));
		assertTrue(ItemRules.isRune("Wrath rune", true));
		assertFalse(ItemRules.isRune("Rune scimitar", false));
		assertFalse(ItemRules.isRune("Rune arrow", true));
	}

	@Test
	public void teleportConsumables()
	{
		assertTrue(ItemRules.isTeleportConsumable("Varrock teleport", "Break"));
		assertTrue(ItemRules.isTeleportConsumable("Lumberyard teleport", "Read"));
		assertFalse(ItemRules.isTeleportConsumable("Teleport crystal (3)", "Teleport"));
		assertFalse(ItemRules.isTeleportConsumable("Varrock teleport", "Drop"));
	}

	@Test
	public void farmingNames()
	{
		assertTrue(ItemRules.isPlantable("Ranarr seed"));
		assertTrue(ItemRules.isPlantable("Magic sapling"));
		assertTrue(ItemRules.isPlantable("Crystal acorn"));
		assertFalse(ItemRules.isPlantable("Grimy ranarr weed"));
		assertEquals("Ranarr", ItemRules.cropFromPlantable("Ranarr seed"));
		assertEquals("Magic", ItemRules.cropFromPlantable("Magic sapling"));
		assertEquals("Palm", ItemRules.cropFromPlantable("Palm sapling"));
		assertEquals("Magic", ItemRules.cropFromPatchAppearance("Magic tree"));
		assertEquals("Yew", ItemRules.cropFromPatchAppearance("Diseased yew tree"));
		assertNull(ItemRules.cropFromPatchAppearance("Herbs"));
		assertNull(ItemRules.cropFromPatchAppearance("Tree stump"));
		assertEquals("Herb", ItemRules.patchCategory("Herb patch"));
		assertEquals("Fruit tree", ItemRules.patchCategory("Fruit Tree Patch"));
		assertEquals("Farming", ItemRules.patchCategory(null));
		assertTrue(ItemRules.isFarmingTool("Watering can(7)"));
		assertTrue(ItemRules.isFarmingTool("Bucket"));
		assertFalse(ItemRules.isFarmingTool("Grimy ranarr weed"));
	}

	@Test
	public void compostMessages()
	{
		assertEquals("Ultracompost", ItemRules.compostFromMessage("You treat the herb patch with ultracompost."));
		assertEquals("Supercompost", ItemRules.compostFromMessage("You treat the tree patch with supercompost."));
		assertNull(ItemRules.compostFromMessage("You plant a ranarr seed in the herb patch."));
	}
}

package com.gildedledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.gildedledger.data.SourceCategory;
import com.gildedledger.data.TrackerData;
import com.gildedledger.ui.LootPrices;
import com.gildedledger.ui.PanelModel;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public class PanelModelTest
{
	private static final int WHIP = 4151;
	private static final int DEFENDER = 12954;
	private static final int CLUE = 2722;

	/** Whip trades for 1.5M; the defender and the clue can't be traded. */
	private static final LootPrices PRICES = new LootPrices()
	{
		@Override
		public long ge(int itemId)
		{
			return itemId == WHIP ? 1_500_000 : 0;
		}

		@Override
		public long highAlch(int itemId)
		{
			return itemId == WHIP ? 72_000 : itemId == DEFENDER ? 30_000 : 0;
		}

		@Override
		public boolean tradeable(int itemId)
		{
			return itemId == WHIP;
		}
	};

	@Test
	public void tradeableLootUsesGeAndUntradeableUsesHighAlch()
	{
		TrackerData data = new TrackerData();
		data.source("npc:Abyssal demon", "Abyssal demon", SourceCategory.COMBAT, 1).addLoot(WHIP, 2, 1);
		data.source("npc:Abyssal demon", "Abyssal demon", SourceCategory.COMBAT, 1).addLoot(DEFENDER, 1, 1);
		data.source("npc:Abyssal demon", "Abyssal demon", SourceCategory.COMBAT, 1).addLoot(CLUE, 1, 1);

		PanelModel.SourceView demon = PanelModel.build(data, PRICES, id -> "item" + id, true).sources.get(0);

		assertEquals(3_000_000 + 30_000, demon.lootValue);
		assertEquals(2 * 72_000 + 30_000, demon.lootHa);
		assertEquals(WHIP, demon.loot.get(0).itemId);
		assertFalse(demon.loot.get(1).tradeable);
		assertEquals(30_000, demon.loot.get(1).value);
	}

	@Test
	public void excludedItemsDoNotCountTowardsProfit()
	{
		TrackerData data = new TrackerData();
		com.gildedledger.data.SourceRecord demon = data.source("npc:Abyssal demon", "Abyssal demon", SourceCategory.COMBAT, 1);
		demon.addLoot(WHIP, 1, 1);
		demon.addLoot(DEFENDER, 1, 1);
		demon.addSupply("2434", 2434, "Prayer potion", "doses", 4, 10_000, 1);
		demon.addSupply("385", 385, "Shark", null, 2, 1_800, 1);

		demon.toggleLootExcluded(DEFENDER);
		demon.toggleSupplyExcluded("385");
		PanelModel.SourceView view = PanelModel.build(data, PRICES, id -> "", true).sources.get(0);
		assertEquals(1_500_000, view.lootValue);
		assertEquals(10_000, view.supplyGp);
		assertTrue(view.loot.stream().anyMatch(l -> l.itemId == DEFENDER && l.excluded));

		// Toggling again counts it once more.
		demon.toggleLootExcluded(DEFENDER);
		assertEquals(1_530_000, PanelModel.build(data, PRICES, id -> "", true).sources.get(0).lootValue);
	}

	@Test
	public void skillsCanBeShownAsOneTable()
	{
		TrackerData data = new TrackerData();
		data.source("item:WOODCUTTING:Yew logs", "Yew logs", SourceCategory.WOODCUTTING, 1).addLoot(WHIP, 3, 1);
		data.source("item:WOODCUTTING:Magic logs", "Magic logs", SourceCategory.WOODCUTTING, 1).addLoot(WHIP, 2, 1);
		data.source("npc:Goblin", "Goblin", SourceCategory.COMBAT, 1).addLoot(WHIP, 1, 1);
		data.source("npc:Cow", "Cow", SourceCategory.COMBAT, 1).addLoot(WHIP, 1, 1);

		assertEquals(4, PanelModel.build(data, PRICES, id -> "", true, false).sources.size());
		List<PanelModel.SourceView> combined = PanelModel.build(data, PRICES, id -> "", true, true).sources;
		assertEquals(3, combined.size());
		PanelModel.SourceView woodcutting = combined.stream()
			.filter(v -> v.category == SourceCategory.WOODCUTTING).findFirst().get();
		assertEquals(5L, woodcutting.loot.get(0).quantity);
		assertEquals(3L, (long) data.sources.get("item:WOODCUTTING:Yew logs").loot.get(WHIP));
	}

	@Test
	public void xpIsSplitBySkillInSkillPanelOrderWithATotal()
	{
		TrackerData data = new TrackerData();
		data.source("npc:Goblin", "Goblin", SourceCategory.COMBAT, 1).addXp("Hitpoints", 40, 1);
		data.source("npc:Goblin", "Goblin", SourceCategory.COMBAT, 1).addXp("Slayer", 20, 1);
		data.source("npc:Goblin", "Goblin", SourceCategory.COMBAT, 1).addXp("Strength", 120, 1);
		data.source("npc:Goblin", "Goblin", SourceCategory.COMBAT, 1).addXp("Attack", 10, 1);

		PanelModel.SourceView goblin = PanelModel.build(data, PRICES, id -> "", true).sources.get(0);

		List<String> order = new ArrayList<>(goblin.xpBySkill.keySet());
		assertEquals(List.of("Attack", "Strength", "Hitpoints", "Slayer"), order);
		assertEquals(190, goblin.xp);
	}
}

package com.gildedledger;

import static org.junit.Assert.assertEquals;
